def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    first = {}
    count = {}
    span = {}
    for i, x in enumerate(a):
        if x not in first:
            first[x] = i
        count[x] = count.get(x, 0) + 1
        span[x] = i - first[x] + 1
    deg = max(count.values())
    part_a = min(span[x] for x in count if count[x] == deg)
    lo, hi = max(a), sum(a)
    while lo < hi:
        mid = (lo + hi) // 2
        pieces = 1
        cur = 0
        for x in a:
            if cur + x > mid:
                pieces += 1
                cur = x
            else:
                cur += x
        if pieces <= k:
            hi = mid
        else:
            lo = mid + 1
    print(part_a)
    print(lo)

