import sys

data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]

def degree(b):
    return max(b.count(x) for x in set(b))

d = degree(a)
part_a = min(j - i + 1 for i in range(n) for j in range(i, n) if degree(a[i:j + 1]) == d)

pre = [0]
for x in a:
    pre.append(pre[-1] + x)
INF = float('inf')
dp = [[INF] * (n + 1) for _ in range(k + 1)]
dp[0][0] = 0
for j in range(1, k + 1):
    for i in range(1, n + 1):
        for t in range(j - 1, i):
            if dp[j - 1][t] != INF:
                dp[j][i] = min(dp[j][i], max(dp[j - 1][t], pre[i] - pre[t]))
print(part_a)
print(dp[k][n])

